LESSON_DB.accounting.m2 = {
  0: {emoji:"📊", subtitle:"Grade 10–12 · Did the business make a profit?",
    illusText:"Sales R45 000 − Cost of sales R30 000 = Gross profit R15 000. Then the expenses start.",
    hook:{title:"Busy isn't the same as profitable", body:"A busy hair salon in Durban seems to make lots of money: R45 000 a month in sales. But after paying for products, wages, rent and loan interest, the owner finds only R1 500 left. The <strong>Income Statement</strong> (Statement of Comprehensive Income) shows exactly where the money goes — and whether the business is really making a profit."},
    intro:"The <strong>Income Statement</strong> covers a period (e.g. a year). Layout: <strong>Sales</strong> − <strong>Cost of sales</strong> = <strong>Gross profit</strong>; + <strong>Other operating income</strong> (rent income, commission, discounts received) = <strong>Gross operating income</strong>; − <strong>Operating expenses</strong> (wages, rent, advertising, depreciation) = <strong>Operating profit</strong>; + interest income − interest expense = <strong>Net profit</strong> (for companies, before and after tax). Year-end adjustments (prepaid, accrued, depreciation) are made first so figures follow the matching principle.",
    concepts:[
      {t:"green", title:"🛍️ Gross profit", body:"Sales minus cost of sales — the profit on trading before running costs."},
      {t:"teal", title:"🏢 Operating expenses", body:"The costs of running the business: wages, rent, water and electricity, advertising, depreciation."},
      {t:"gold", title:"🏦 Finance items", body:"Interest income is added and interest on loans is deducted after operating profit."},
    ],
    examples:[
      {title:"Gross profit", body:"Sales R45 000; cost of sales R30 000.", answer:"45 000 − 30 000 = <strong>R15 000</strong>."},
      {title:"Operating profit", body:"Gross profit R15 000; rent income R2 000; wages R9 000; rent expense R6 000.", answer:"15 000 + 2 000 = 17 000 − 15 000 = <strong>R2 000</strong>."},
      {title:"Net profit", body:"Operating profit R2 000; interest on loan R500.", answer:"2 000 − 500 = <strong>R1 500</strong>."},
    ],
    formula:"Gross profit = Sales − Cost of sales · Net profit = Gross profit + Other income − Expenses ± Interest",
    mistakes:["Including drawings as an expense.","Putting interest expense among operating expenses (it's shown separately).","Forgetting year-end adjustments before calculating profit."],
    callout:{title:"The real test", body:"Sales show how busy a business is; net profit shows whether it's worth doing."},
    activity:"Sales R80 000; cost of sales R50 000; commission income R3 000; operating expenses R24 000; interest expense R1 200. Calculate gross profit, operating profit and net profit.",
    activityAnswer:"GP = 30 000. Gross operating income = 33 000. Operating profit = 33 000 − 24 000 = 9 000. Net profit = 9 000 − 1 200 = <strong>R7 800</strong>.",
    examTip:"Use the official headings in the correct order. Many marks are for layout and subtotals, not just the final answer.",
    keyterms:[{w:"Gross profit",d:"Sales minus cost of sales"},{w:"Operating expenses",d:"Costs of running the business"},{w:"Net profit",d:"Profit after all income and expenses"}],
    quiz:[
      {q:"Sales R60 000, cost of sales R40 000. Gross profit:",opts:["R100 000","R20 000","R40 000","R60 000"],a:1,et:"60 000 − 40 000."},
      {q:"Which is NOT an operating expense?",opts:["Wages","Rent expense","Drawings","Advertising"],a:2,et:"Drawings reduce equity, not profit."},
      {q:"Interest on a loan is:",opts:["Added to sales","Deducted after operating profit","Part of cost of sales","Ignored"],a:1,et:"It's a finance cost."},
    ],
    conclusion:"Gross profit, operating profit, net profit — each line tells you something different about how the business earns its money."},

  1: {emoji:"👥", subtitle:"Grade 10–12 · How owner's equity changed during the year",
    illusText:"Opening capital + profit − drawings = closing capital. For companies: retained income.",
    hook:{title:"Where did the profit end up?", body:"The salon made R1 500 net profit, but the owner took R4 000 in drawings. So the owner's stake in the business actually <em>fell</em>. A <strong>statement of owner's equity</strong> (or, for companies, the equity notes and statement of changes in equity) shows how the owners' stake changed during the year — and why."},
    intro:"For a <strong>sole trader</strong>, the owner's equity note shows: capital at the beginning, plus capital contributed, plus net profit (or minus net loss), minus drawings = capital at the end. For a <strong>company</strong>, equity is <strong>ordinary share capital</strong> plus <strong>retained income</strong>. Retained income: opening balance + net profit after tax − dividends = closing balance. Shares issued increase share capital; share buy-backs reduce it.",
    concepts:[
      {t:"green", title:"🧑‍💼 Sole trader", body:"Capital changes with contributions, profit or loss, and drawings."},
      {t:"teal", title:"🏢 Companies", body:"Shareholders own the company. Profits not paid out as dividends are kept as retained income."},
      {t:"gold", title:"💸 Dividends", body:"Interim and final dividends reduce retained income — they're a distribution of profit, not an expense."},
    ],
    examples:[
      {title:"Sole trader", body:"Opening capital R50 000; net profit R1 500; drawings R4 000.", answer:"50 000 + 1 500 − 4 000 = <strong>R47 500</strong>."},
      {title:"Retained income", body:"Opening R200 000; net profit after tax R90 000; dividends R60 000.", answer:"200 000 + 90 000 − 60 000 = <strong>R230 000</strong>."},
      {title:"Shares issued", body:"A company issues 100 000 new shares at R5 each.", answer:"Ordinary share capital increases by <strong>R500 000</strong>."},
    ],
    formula:"Retained income (end) = Retained income (start) + Net profit after tax − Dividends",
    mistakes:["Treating dividends as an expense in the income statement.","Mixing up share capital and retained income.","Adding drawings instead of subtracting."],
    callout:{title:"Reinvesting", body:"Many growing companies pay small dividends and keep most profit as retained income to fund expansion."},
    activity:"A company's retained income was R350 000. Net profit after tax was R140 000; interim dividends R40 000 and final dividends R55 000. Calculate closing retained income.",
    activityAnswer:"350 000 + 140 000 − 40 000 − 55 000 = <strong>R395 000</strong>.",
    examTip:"Label every line (opening balance, net profit, dividends, closing balance). Partial marks are awarded for correct items.",
    keyterms:[{w:"Retained income",d:"Accumulated profits kept in the company"},{w:"Dividends",d:"Profits paid out to shareholders"},{w:"Share capital",d:"Money raised by issuing shares"}],
    quiz:[
      {q:"Opening capital R50 000, net profit R1 500, drawings R4 000. Closing capital:",opts:["R55 500","R47 500","R52 500","R45 500"],a:1,et:"50 000 + 1 500 − 4 000."},
      {q:"Dividends paid reduce:",opts:["Sales","Retained income","Share capital","Liabilities"],a:1,et:"They distribute retained profits."},
      {q:"Equity of a company consists of:",opts:["Capital and drawings","Share capital and retained income","Debtors and creditors","Bank and cash"],a:1,et:"The shareholders' equity."},
    ],
    conclusion:"Equity tells the owners' story: what they put in, what the business earned, and what they took out."},

  2: {emoji:"🏛️", subtitle:"Grade 10–12 · What the business owns and owes on one day",
    illusText:"Total assets R152 000 = Equity and liabilities R152 000. A photo of the business on one date.",
    hook:{title:"A photo, not a video", body:"The Income Statement is like a video of the year. The <strong>Balance Sheet</strong> (Statement of Financial Position) is a photo taken on one day: what the business owns and what it owes. A bank deciding whether to lend money to a spaza owner looks first at this photo — can the business pay its debts?"},
    intro:"The <strong>Balance Sheet</strong> shows the financial position on a specific date. <strong>Assets</strong>: non-current (fixed/tangible assets at carrying value, fixed deposits) and current (inventories, trade and other receivables, cash and cash equivalents). <strong>Equity and liabilities</strong>: owner's equity (or share capital + retained income), non-current liabilities (long-term loans) and current liabilities (trade and other payables, bank overdraft, current portion of loan). Total assets must equal total equity and liabilities. <strong>Working capital</strong> = current assets − current liabilities.",
    concepts:[
      {t:"green", title:"🏗️ Non-current vs current", body:"Non-current: used for more than a year. Current: converted to cash or settled within a year."},
      {t:"teal", title:"📑 Notes", body:"Most figures come from notes, e.g. trade and other receivables = debtors + prepaid expenses + accrued income."},
      {t:"gold", title:"💧 Working capital", body:"Positive working capital means the business can pay its short-term debts."},
    ],
    examples:[
      {title:"Total assets", body:"Equipment R120 000; inventories R18 000; receivables R9 500; cash R4 500.", answer:"Current assets 32 000 → total assets <strong>R152 000</strong>."},
      {title:"Does it balance?", body:"Owner's equity R100 000; loan R30 000; creditors R22 000.", answer:"100 000 + 30 000 + 22 000 = <strong>R152 000</strong> = total assets. Balanced."},
      {title:"Working capital", body:"Current assets R32 000; current liabilities R22 000.", answer:"32 000 − 22 000 = <strong>R10 000</strong>."},
    ],
    formula:"Total assets = Equity + Liabilities · Working capital = Current assets − Current liabilities",
    mistakes:["Listing a bank overdraft as an asset — it's a current liability.","Showing fixed assets at cost instead of carrying value.","Forgetting the current portion of a long-term loan under current liabilities."],
    callout:{title:"Read it like a banker", body:"Check the working capital, the size of loans compared with equity, and whether cash is enough to cover short-term debts."},
    activity:"Vehicles (carrying value) R180 000; inventory R25 000; debtors R14 000; bank overdraft R6 000; creditors R18 000; loan R70 000. Calculate total assets and owner's equity.",
    activityAnswer:"Total assets = 180 000 + 25 000 + 14 000 = <strong>R219 000</strong>. Liabilities = 6 000 + 18 000 + 70 000 = 94 000. Owner's equity = 219 000 − 94 000 = <strong>R125 000</strong>.",
    examTip:"Use the official headings and subtotals. Show where each figure comes from (e.g. “see note 3”).",
    keyterms:[{w:"Balance sheet",d:"Statement of financial position on a specific date"},{w:"Carrying value",d:"Cost minus accumulated depreciation"},{w:"Working capital",d:"Current assets minus current liabilities"}],
    quiz:[
      {q:"A bank overdraft is a:",opts:["Current asset","Current liability","Non-current asset","Income"],a:1,et:"It's owed to the bank."},
      {q:"Current assets R32 000, current liabilities R22 000. Working capital:",opts:["R54 000","R10 000","R−10 000","R22 000"],a:1,et:"32 000 − 22 000."},
      {q:"Fixed assets are shown at:",opts:["Selling price","Carrying value","Replacement cost","Zero"],a:1,et:"Cost minus accumulated depreciation."},
    ],
    conclusion:"The balance sheet is a snapshot. Assets on one side, claims on the other — and they must balance."},

  3: {emoji:"🌊", subtitle:"Grade 12 · Profit isn't the same as cash",
    illusText:"A profitable business can still run out of cash — the cash flow statement shows why.",
    hook:{title:"Profitable but broke", body:"A Gauteng printing company makes a healthy profit, but in March it can't pay salaries. How? It bought a new R120 000 printer, and its big customers haven't paid yet. Profit and cash are different things. The <strong>Cash Flow Statement</strong> explains exactly how cash came in and went out during the year."},
    intro:"The <strong>Cash Flow Statement</strong> (Grade 12, companies) shows the change in cash and cash equivalents during the year, in three sections. <strong>Operating activities</strong>: cash from the business's main trading (cash generated from operations, interest paid, tax paid and other items as set out in your textbook's format). <strong>Investing activities</strong>: buying and selling fixed assets and investments. <strong>Financing activities</strong>: issuing or buying back shares, and receiving or repaying loans. Net change in cash + opening cash = closing cash.",
    concepts:[
      {t:"green", title:"⚙️ Operating", body:"Cash from day-to-day trading. Profit is adjusted for non-cash items (like depreciation) and changes in working capital."},
      {t:"teal", title:"🏗️ Investing", body:"Buying a vehicle or equipment = cash out. Selling an asset = cash in."},
      {t:"gold", title:"🏦 Financing", body:"New shares or loans = cash in. Loan repayments or share buy-backs = cash out."},
    ],
    examples:[
      {title:"Net change", body:"Operating +R85 000; investing −R120 000; financing +R50 000.", answer:"85 000 − 120 000 + 50 000 = <strong>+R15 000</strong>."},
      {title:"Closing cash", body:"Opening cash and cash equivalents R20 000.", answer:"20 000 + 15 000 = <strong>R35 000</strong>."},
      {title:"Classify", body:"(a) Bought a delivery vehicle. (b) Received a long-term loan.", answer:"(a) <strong>Investing</strong> (cash out). (b) <strong>Financing</strong> (cash in)."},
    ],
    formula:"Net change in cash = Operating + Investing + Financing · Closing cash = Opening cash + Net change",
    mistakes:["Treating depreciation as a cash outflow — it's a non-cash expense.","Putting the purchase of fixed assets under operating activities.","Getting the signs wrong (cash in +, cash out −)."],
    callout:{title:"Cash is king", body:"Many small businesses that close were profitable on paper but ran out of cash. Watching cash flow keeps the lights on."},
    activity:"Operating activities +R42 000; bought equipment R65 000; sold an old vehicle R18 000; repaid a loan R10 000. Opening cash R30 000. Calculate closing cash.",
    activityAnswer:"Investing: −65 000 + 18 000 = −47 000. Financing: −10 000. Net change: 42 000 − 47 000 − 10 000 = −15 000. Closing cash = 30 000 − 15 000 = <strong>R15 000</strong>.",
    examTip:"Use brackets for outflows and show each section's subtotal. Check that the closing cash matches the balance sheet.",
    keyterms:[{w:"Operating activities",d:"Cash flows from main trading activities"},{w:"Investing activities",d:"Cash flows from buying and selling fixed assets"},{w:"Financing activities",d:"Cash flows from shares and loans"}],
    quiz:[
      {q:"Buying a vehicle is a(n):",opts:["Operating activity","Investing activity","Financing activity","Non-cash item"],a:1,et:"Purchase of a fixed asset."},
      {q:"Receiving a long-term loan is a(n):",opts:["Operating activity","Investing activity","Financing activity","Expense"],a:2,et:"It's how the business is financed."},
      {q:"Opening cash R20 000; net change +R15 000. Closing cash:",opts:["R5 000","R35 000","R15 000","R20 000"],a:1,et:"20 000 + 15 000."},
    ],
    conclusion:"Profit is an opinion shaped by accounting rules; cash is a fact. The cash flow statement links the two."},

  4: {emoji:"📝", subtitle:"Grade 11–12 · The detail behind the figures",
    illusText:"A R300 000 vehicle loses R60 000 a year on the straight-line method at 20%.",
    hook:{title:"Why is the bakkie worth less?", body:"A business bought a delivery bakkie for R300 000 two years ago. On the balance sheet it's now shown at R180 000. Did someone make a mistake? No — the <strong>notes</strong> explain: R120 000 of <strong>depreciation</strong> has been recorded, spreading the cost of the vehicle over the years it's used. Notes give readers the detail behind every figure."},
    intro:"<strong>Notes to the financial statements</strong> explain how figures were calculated. Common notes: <strong>fixed/tangible assets</strong> (cost, accumulated depreciation, carrying value, additions and disposals), <strong>inventories</strong>, <strong>trade and other receivables</strong> (debtors + prepaid expenses + accrued income), <strong>cash and cash equivalents</strong>, <strong>trade and other payables</strong> (creditors + accrued expenses + income received in advance) and equity notes. <strong>Depreciation</strong>: straight-line (fixed % of cost) or diminishing balance (fixed % of carrying value).",
    concepts:[
      {t:"green", title:"📉 Straight-line", body:"Same amount each year: cost × rate. A R300 000 vehicle at 20% → R60 000 a year."},
      {t:"teal", title:"📉 Diminishing balance", body:"Rate × carrying value, so the amount falls each year: year 1 R60 000, year 2 R48 000 (20% of R240 000)."},
      {t:"gold", title:"📂 Receivables and payables", body:"Prepaid expenses and accrued income are assets; accrued expenses and income received in advance are liabilities."},
    ],
    examples:[
      {title:"Straight-line", body:"Vehicle cost R300 000; 20% p.a. on cost. Carrying value after 2 years?", answer:"Depreciation 60 000 × 2 = 120 000 → <strong>R180 000</strong>."},
      {title:"Diminishing balance", body:"Same vehicle, 20% p.a. on carrying value. Carrying value after 2 years?", answer:"Year 1: 300 000 − 60 000 = 240 000. Year 2: 240 000 − 48 000 = <strong>R192 000</strong>."},
      {title:"Receivables note", body:"Debtors R9 000; prepaid insurance R1 200; accrued interest income R300.", answer:"Trade and other receivables = <strong>R10 500</strong>."},
    ],
    formula:"Straight-line: Cost × % · Diminishing balance: Carrying value × % · Carrying value = Cost − Accumulated depreciation",
    mistakes:["Using cost instead of carrying value for diminishing balance.","Forgetting to calculate depreciation for part of a year on assets bought mid-year.","Putting income received in advance under receivables (it's a liability)."],
    callout:{title:"Part-years", body:"An asset bought on 1 October with a 28 February year-end is depreciated for 5 months: annual amount × 5/12."},
    activity:"Equipment costing R48 000 is depreciated at 15% p.a. on the diminishing-balance method. Calculate depreciation for years 1 and 2.",
    activityAnswer:"Year 1: 15% × 48 000 = R7 200 → carrying value 40 800. Year 2: 15% × 40 800 = <strong>R6 120</strong>.",
    examTip:"Set out the fixed-asset note in the standard columns (land and buildings, vehicles, equipment) and show workings for depreciation.",
    keyterms:[{w:"Depreciation",d:"Spreading an asset's cost over its useful life"},{w:"Accumulated depreciation",d:"Total depreciation recorded to date"},{w:"Prepaid expense",d:"An expense paid in advance — a current asset"}],
    quiz:[
      {q:"R300 000 at 20% straight-line. Annual depreciation:",opts:["R6 000","R60 000","R48 000","R240 000"],a:1,et:"20% × 300 000."},
      {q:"Diminishing-balance depreciation is based on:",opts:["Cost","Carrying value","Selling price","Market value"],a:1,et:"The amount falls each year."},
      {q:"Income received in advance is a(n):",opts:["Asset","Liability","Expense","Income"],a:1,et:"The business owes the service."},
    ],
    conclusion:"Notes turn totals into explanations. Depreciation, receivables and payables are where the detail lives."},

  5: {emoji:"📐", subtitle:"Grade 11–12 · Reading a business's health in a few numbers",
    illusText:"Current ratio 1.45 : 1, acid-test 0.64 : 1, gross margin 33.3% — what do they say?",
    hook:{title:"Should the bank lend?", body:"A clothing shop asks the bank for a R100 000 loan. The loan officer doesn't read every line of the statements — she calculates a few <strong>ratios</strong>. Can the shop pay its short-term debts? How profitable is each sale? How much does it already owe? In a few minutes, the ratios tell her the story."},
    intro:"<strong>Ratio analysis</strong> compares figures to judge a business. <strong>Liquidity</strong>: current ratio = current assets : current liabilities; acid-test ratio = (current assets − inventories) : current liabilities. <strong>Profitability</strong>: gross profit on sales % = GP ÷ sales × 100; mark-up on cost % = GP ÷ cost of sales × 100; net profit on sales %. <strong>Solvency and risk</strong>: debt-equity ratio = non-current liabilities : equity. <strong>Returns</strong>: return on owner's equity = net profit ÷ average equity × 100. Always compare with the previous year, the industry and the business's targets.",
    concepts:[
      {t:"green", title:"💧 Liquidity", body:"Can the business pay short-term debts? A current ratio around 2 : 1 is often seen as comfortable; the acid-test removes stock, which may be slow to sell."},
      {t:"teal", title:"💰 Profitability", body:"Gross margin and net margin show how much of each rand of sales becomes profit."},
      {t:"gold", title:"🏋️ Gearing", body:"A high debt-equity ratio means more borrowed money — higher risk, but possibly higher returns."},
    ],
    examples:[
      {title:"Current and acid-test", body:"Current assets R32 000 (inventories R18 000); current liabilities R22 000.", answer:"Current ratio 32 000 : 22 000 = <strong>1.45 : 1</strong>. Acid-test 14 000 : 22 000 = <strong>0.64 : 1</strong> — the business relies on selling stock to pay debts."},
      {title:"Margins", body:"Sales R45 000; cost of sales R30 000; gross profit R15 000.", answer:"GP on sales = 15 000 ÷ 45 000 × 100 = <strong>33.3%</strong>. Mark-up on cost = 15 000 ÷ 30 000 × 100 = <strong>50%</strong>."},
      {title:"Debt-equity", body:"Loan R30 000; owner's equity R100 000.", answer:"30 000 : 100 000 = <strong>0.3 : 1</strong> — low gearing, low financial risk."},
    ],
    formula:"Current ratio = CA : CL · Acid-test = (CA − Inventories) : CL · GP % on sales = GP ÷ Sales × 100",
    mistakes:["Calculating a ratio without commenting on what it means.","Confusing mark-up on cost with gross profit on sales.","Comparing a ratio with nothing — always compare with last year or a benchmark."],
    callout:{title:"Interpret, don't just calculate", body:"Exams reward the comment: state the ratio, say whether it improved or worsened, and explain what it means for the business."},
    activity:"Last year the current ratio was 2.1 : 1; this year it's 1.45 : 1. The acid-test fell from 1.1 : 1 to 0.64 : 1. Comment on the liquidity.",
    activityAnswer:"Liquidity has <strong>worsened</strong>. The business has less cover for short-term debts and now depends on selling stock to pay them (acid-test below 1 : 1). It should collect debtors faster, control stock levels or reduce current liabilities.",
    examTip:"Give the ratio with its formula and workings, then a comment with a reason and a suggestion — three steps, three sets of marks.",
    keyterms:[{w:"Current ratio",d:"Current assets compared with current liabilities"},{w:"Acid-test ratio",d:"Current assets minus inventories, compared with current liabilities"},{w:"Debt-equity ratio",d:"Non-current liabilities compared with equity"}],
    quiz:[
      {q:"CA R40 000, CL R20 000. Current ratio:",opts:["0.5 : 1","2 : 1","20 : 1","1 : 2"],a:1,et:"40 000 ÷ 20 000 = 2."},
      {q:"The acid-test ratio excludes:",opts:["Cash","Debtors","Inventories","Creditors"],a:2,et:"Stock may be slow to turn into cash."},
      {q:"GP R15 000, cost of sales R30 000. Mark-up on cost:",opts:["33.3%","50%","200%","15%"],a:1,et:"15 000 ÷ 30 000 × 100."},
    ],
    conclusion:"Ratios turn statements into a story about liquidity, profit and risk. Calculate carefully — then explain what they mean."},
};

